UPDATE qa_document
SET status = 'PARSING', error_message = NULL, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE qa_document
SET status = 'FAILED', error_message = #{errorMessage}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE qa_document
SET error_message = #{note}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
